#!/usr/bin/env bash
set -euo pipefail
PROJECT_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)";BUILD_ROOT="$PROJECT_ROOT/build/sm64-modern-bowser-tail-anchor";mkdir -p "$BUILD_ROOT/module-cache";xcrun swiftc -parse-as-library -swift-version 6 -Xfrontend -strict-concurrency=complete -module-cache-path "$BUILD_ROOT/module-cache" "$PROJECT_ROOT/SM64Modern/BowserTailAnchorBehavior.swift" "$PROJECT_ROOT/tests/sm64_modern_bowser_tail_anchor_smoke.swift" -o "$BUILD_ROOT/smoke";sout="$($BUILD_ROOT/smoke)";printf '%s\n' "$sout";xcrun clang -std=c11 "$PROJECT_ROOT/tests/sm64_modern_bowser_tail_anchor_contract.c" -o "$BUILD_ROOT/contract";cout="$($BUILD_ROOT/contract)";printf '%s\n' "$cout";s="$(printf '%s\n' "$sout"|sed -n 's/^bowserTailAnchorFingerprint=//p')";c="$(printf '%s\n' "$cout"|sed -n 's/^bowserTailAnchorFingerprint=//p')";[[ -n "$s"&&"$s" == "$c" ]]||{ echo "Bowser tail anchor mismatch Swift=$s C=$c" >&2;exit 1;};printf '%s\n' 'Swift/C Bowser tail anchor contract matched'
